method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0  // Precondition: lst must be a non-empty list
    requires forall i :: 0 <= i < |lst| ==> (lst[i] % 2 == 0 || lst[i] % 2 != 0) // All elements are integers
    ensures result == SumEvenAtOddIndices(lst) // Postcondition: result is the sum of even elements at odd indices

method SumEvenAtOddIndices(lst: seq<int>) returns (sum: int)
    // Helper method to calculate the sum of even elements at odd indices
    requires |lst| > 0
    ensures sum == (if |lst| == 0 then 0 else SumEvenAtOddIndicesHelper(lst, 1, 0))

method SumEvenAtOddIndicesHelper(lst: seq<int>, index: int, acc: int) returns (sum: int)
    requires |lst| > 0
    requires 0 <= index <= |lst| // Index must be within the bounds of the list
    requires acc >= 0 // Accumulator must be non-negative
    ensures sum == acc + (if index < |lst| && index % 2 == 1 && lst[index] % 2 == 0 then lst[index] else 0) + SumEvenAtOddIndicesHelper(lst, index + 1, acc + (if index < |lst| && index % 2 == 1 && lst[index] % 2 == 0 then lst[index] else 0))
{
    if index < |lst| {
        // Check if the current index is odd and the element is even
        if index % 2 == 1 && lst[index] % 2 == 0 {
            return SumEvenAtOddIndicesHelper(lst, index + 1, acc + lst[index]);
        } else {
            return SumEvenAtOddIndicesHelper(lst, index + 1, acc);
        }
    } else {
        return acc; // Base case: return accumulated sum
    }
}
